import { variantsFor } from "./thumbnails/resize.js";

const SUPPORTED = new Set(["image/jpeg", "image/png", "image/webp"]);

export interface Upload {
  contentType: string;
  bytes: number;
  width: number;
}

export function accept(upload: Upload): { status: number; reason?: string; variants?: number[] } {
  if (!SUPPORTED.has(upload.contentType)) return { status: 415, reason: "unsupported type" };
  if (!withinUploadLimit(upload.bytes)) return { status: 413, reason: "too large" };
  return { status: 202, variants: variantsFor(upload.width) };
}

